  const recipe=id=>C.alchemistRecipe?.(id)||recipes().find(x=>x.id===id),method=id=>C.alchemistMethod?.(id)||methods().find(x=>x.id===id),action=id=>C.alchemistAction?.(id)||actions().find(x=>x.id===id),technique=id=>C.alchemistTechnique?.(id)||techniques().find(x=>x.id===id),alchTool=id=>C.alchemistTool?.(id)||tools().find(x=>x.id===id),alchGear=id=>C.alchemistGear?.(id)||gearDefs().find(x=>x.id===id),specDef=id=>C.alchemistSpecialization?.(id)||specDefs().find(x=>x.id===id),marketItem=id=>C.alchemistMarketItem?.(id)||marketDefs().find(x=>x.id===id),catalyst=id=>C.alchemistCatalyst?.(id)||catalysts().find(x=>x.id===id),researchProject=id=>C.alchemistResearchProject?.(id)||researchProjects().find(x=>x.id===id),advancedLab=id=>C.alchemistAdvancedLab?.(id)||advancedLabs().find(x=>x.id===id),scholarlyNetwork=id=>C.alchemistScholarlyNetwork?.(id)||scholarlyNetworks().find(x=>x.id===id),exceptionalOrder=id=>C.alchemistExceptionalOrder?.(id)||exceptionalOrders().find(x=>x.id===id),masterySeal=id=>C.alchemistMasterySeal?.(id)||masterySeals().find(x=>x.id===id),masterCareer=()=>C.alchemistMasterCareer?.(JOB)||masterCareers().find(x=>x.jobId===JOB)||null,S=()=>C.jobState(JOB),rankOrder=()=>Number(S().rankOrder||0);
  const clients=()=>C.content.jobClients.filter(x=>x.jobId===JOB),contracts=()=>C.content.jobContracts.filter(x=>x.jobId===JOB),uid=()=>`al_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
