  function ownsAdvancedLab(id){return S().advancedLaboratories.owned.includes(id);}function activeAdvancedLab(){const id=S().advancedLaboratories.active;return id&&ownsAdvancedLab(id)?advancedLab(id):null;}
  function activeLabEffect(key){return Number(activeAdvancedLab()?.effects?.[key]||0);}function networkState(id){if(!S().scholarlyNetworks[id])S().scholarlyNetworks[id]={joined:false,standing:0,publications:0};return S().scholarlyNetworks[id];}
  function networkJoined(id){return !!networkState(id).joined;}function networkStanding(id){return clamp(networkState(id).standing||0);}function networkPerks(n){const st=networkStanding(n?.id);return (n?.perks||[]).filter(p=>st>=Number(p.minStanding||0));}
