  function advancedLabRequirementRows(l){const rows=[],add=(label,have,need)=>rows.push({label,have:Number(have||0),need:Number(need||0),ok:Number(have||0)>=Number(need||0)});add('Niveau Alchimiste',S().level,l.minLevel||1);add('Grade professionnel',rankOrder(),l.minRank||0);add('Réputation',S().reputation,l.minReputation||0);for(const id of l.requiresResearch||[])rows.push({label:`Recherche : ${researchProject(id)?.name||id}`,have:researchCompleted(id)?1:0,need:1,ok:researchCompleted(id)});for(const id of l.requiresLabs||[])rows.push({label:`Annexe : ${advancedLab(id)?.name||id}`,have:ownsAdvancedLab(id)?1:0,need:1,ok:ownsAdvancedLab(id)});return rows;}
