  function buildAdvancedLab(id){ensure();const l=advancedLab(id);if(!l||ownsAdvancedLab(id))return;const rows=advancedLabRequirementRows(l),costs=advancedLabCostRows(l);if(rows.some(x=>!x.ok))return alert('Le laboratoire ne remplit pas encore les prérequis de cette annexe.');if(costs.some(x=>x.have<x.need))return alert('Les ressources nécessaires à cette annexe ne sont pas disponibles.');for(const c of costs){if(c.id==='treasury')C.state.treasury-=c.need;else C.consumeResource(c.id,c.need,`Laboratoire avancé — ${l.name}`);}S().advancedLaboratories.owned.push(l.id);if(!S().advancedLaboratories.active)S().advancedLaboratories.active=l.id;S().stats.advancedLabsBuilt=S().advancedLaboratories.owned.length;C.gainJobXp(JOB,18+Number(l.minRank||0)*3);C.gainVillageXp(5);C.log(`${l.icon||'🔬'} Annexe construite : ${l.name}.`);C.evaluateAchievements?.(false);C.save();render();}
  function activateAdvancedLab(id){ensure();if(activeTask())return alert('Termine le travail en cours avant de reconfigurer le laboratoire.');if(!ownsAdvancedLab(id))return;S().advancedLaboratories.active=id;S().stats.labConfigurations++;C.log(`🔬 Configuration active : ${advancedLab(id)?.name||id}.`);C.save();render();}
  function networkRequirementRows(n){const rows=[],add=(label,have,need)=>rows.push({label,have:Number(have||0),need:Number(need||0),ok:Number(have||0)>=Number(need||0)});add('Niveau Alchimiste',S().level,n.minLevel||1);add('Grade professionnel',rankOrder(),n.minRank||0);add('Réputation',S().reputation,n.minReputation||0);for(const id of n.requiresResearch||[])rows.push({label:`Recherche : ${researchProject(id)?.name||id}`,have:researchCompleted(id)?1:0,need:1,ok:researchCompleted(id)});for(const [id,need] of Object.entries(n.requiresNetworks||{}))add(`Réseau : ${scholarlyNetwork(id)?.name||id}`,networkStanding(id),need);return rows;}
  function joinScholarlyNetwork(id){ensure();const n=scholarlyNetwork(id),st=networkState(id);if(!n||st.joined)return;const rows=networkRequirementRows(n),cost=Number(n.joinCost||0);if(rows.some(x=>!x.ok))return alert('Les conditions d’admission de ce réseau ne sont pas encore réunies.');if(Number(C.state.treasury||0)<cost)return alert(`Il faut ${cost} couronnes pour les frais de correspondance et d’inscription.`);C.state.treasury-=cost;st.joined=true;st.standing=Math.max(Number(st.standing||0),8);S().stats.networksJoined=scholarlyNetworks().filter(x=>networkJoined(x.id)).length;C.gainJobXp(JOB,12);C.log(`${n.icon||'📚'} Réseau savant rejoint : ${n.name}.`);C.evaluateAchievements?.(false);C.save();render();}
  function publicationLots(n){const p=n?.publication||{};return S().alchemicalLots.filter(l=>l.resourceId===p.resourceId&&Number(l.quantity||0)>0&&Number(l.quality||0)>=Number(p.qualityMin||0)&&Number(l.stability||0)>=Number(p.stabilityMin||0)).sort((a,b)=>Number(a.quality||0)-Number(b.quality||0));}
  function consumeTrackedLots(lots,qty){let need=Number(qty||0),qsum=0,ssum=0,psum=0,used=0;for(const l of lots){if(need<=0)break;const take=Math.min(need,Number(l.quantity||0));l.quantity-=take;need-=take;used+=take;qsum+=take*Number(l.quality||0);ssum+=take*Number(l.stability||0);psum+=take*Number(l.catalystPurity||0);}S().alchemicalLots=S().alchemicalLots.filter(l=>Number(l.quantity||0)>1e-9);return {used,missing:need,quality:used?qsum/used:0,stability:used?ssum/used:0,catalystPurity:used?psum/used:0};}
  function publishScholarlyMemoir(id){ensure();const n=scholarlyNetwork(id),st=networkState(id),p=n?.publication||{};if(!n||!st.joined)return;const max=Number(p.max||0);if(Number(st.publications||0)>=max)return alert('Le réseau a déjà reçu toutes les contributions prévues pour cette étape de carrière.');const qty=Number(p.quantity||1),lots=publicationLots(n);if(lots.reduce((a,l)=>a+Number(l.quantity||0),0)<qty||C.resource(p.resourceId)<qty)return alert('Aucun lot qualitatif conforme n’est disponible pour cette publication.');if(Number(C.state.treasury||0)<Number(p.treasury||0))return alert('Les frais de copie, scellement et correspondance ne sont pas disponibles.');const out=consumeTrackedLots(lots,qty);C.consumeResource(p.resourceId,qty,`Mémoire savant — ${n.name}`);C.state.treasury-=Number(p.treasury||0);st.publications=Number(st.publications||0)+1;const gained=gainNetworkStanding(n.id,Number(p.standing||0));S().stats.scholarlyPublications++;C.gainJobXp(JOB,8+Math.round(out.quality/20));C.log(`📚 Mémoire envoyé au ${n.name} · Q${Math.round(out.quality)} · stabilité ${Math.round(out.stability)}% · +${gained} réputation savante.`);C.evaluateAchievements?.(false);C.save();render();}
  function exceptionalCompleted(id){return S().exceptionalHistory.some(x=>x.orderId===id&&x.status==='delivered');}function exceptionalActive(id){return S().activeExceptionalOrders.some(x=>x.orderId===id);}
  function exceptionalLimit(){return Math.max(1,1+Math.round(activeLabEffect('exceptionalSlots')+networkEffect('exceptionalSlots')));}
  function exceptionalEligible(o){if(!o||exceptionalCompleted(o.id)||exceptionalActive(o.id))return false;return S().level>=Number(o.minLevel||1)&&rankOrder()>=Number(o.minRank||0)&&S().reputation>=Number(o.minReputation||0)&&networkJoined(o.networkId)&&networkStanding(o.networkId)>=Number(o.minStanding||0)&&ownsAdvancedLab(o.labId)&&formulaAccessible(recipe(o.alchemyCriteria?.recipeId));}
  function acceptExceptionalOrder(id){ensure();const o=exceptionalOrder(id);if(!o||!exceptionalEligible(o))return;if(S().activeExceptionalOrders.length>=exceptionalLimit())return alert(`Le laboratoire ne peut suivre que ${exceptionalLimit()} mandat(s) exceptionnel(s) en parallèle.`);S().activeExceptionalOrders.push({id:uid(),orderId:o.id,acceptedAt:now(),dueAt:now()+Number(o.duration||900)*1000});S().stats.exceptionalOrdersAccepted++;C.log(`👑 Mandat exceptionnel accepté : ${o.name}.`);C.save();render();}
