  function renderSkills(){const rows=skills().map(sk=>{const lvl=skillLevel(sk.id),xp=Number(S().alchemySkills[sk.id]||0),next=lvl>=10?SK_THRESH[9]:SK_THRESH[lvl],prev=SK_THRESH[Math.max(0,lvl-1)]||0;return `<article class="contract-card"><div class="contract-card-head"><h3>${sk.icon} ${esc(sk.name)}</h3><span class="badge">Niv. ${lvl}/10</span></div><p>${esc(sk.description)}</p>${bar(lvl>=10?1:(xp-prev)/Math.max(1,next-prev),1)}<small>Expérience ${Math.round(xp)}${lvl>=10?' · maîtrise technique':` · prochain niveau ${next}`}</small></article>`;}).join('');$('#alchemistSkills').innerHTML=`<div class="card-grid">${rows}</div>`;}
