  function renderLots(){const ls=S().alchemicalLots.filter(l=>Number(l.quantity||0)>0);$('#alchemistLots').innerHTML=ls.length?`<div class="card-grid">${ls.map(l=>{const r=recipe(l.recipeId),m=method(l.methodId),techNames=Object.values(l.techniqueIds||{}).map(id=>technique(id)?.name).filter(Boolean),toolNames=Object.values(l.toolIds||{}).map(id=>alchTool(id)?.name).filter(Boolean);return `<article class="contract-card"><div class="contract-card-head"><h3>${r?.icon||'🧪'} ${esc(resourceDef(l.resourceId)?.name||l.resourceId)}</h3><span class="badge">${l.unique?'✨ ':''}Q${Math.round(l.quality)}</span></div><p>${fmt(l.quantity)} unité(s) · stabilité <b>${Math.round(l.stability)}%</b> · valeur marché <b>${lotPrice(l)} 🪙</b></p><small>${esc(m?.name||'Procédé')} · matières Q${Math.round(l.inputQuality||45)} · ${Number(l.traceableInput||0)>0?`${fmt(l.traceableInput)} unité(s) issues de lots Herboriste traçables`:'matières issues du stock courant'}${lotControlled(l)?' · <b>lot sous contrôle</b>':''}${Number(l.catalystPurity||0)>0?` · catalyseur ${Math.round(l.catalystPurity)}%`:''}${techNames.length?`<br>Gestes : ${techNames.map(esc).join(' · ')}`:''}${toolNames.length?`<br>Matériel : ${toolNames.map(esc).join(' · ')}`:''}</small></article>`;}).join('')}</div>`:'<div class="empty-state">Aucun lot qualitatif. Les jobs autonomes peuvent produire du stock courant, mais seuls les lots actifs conservent qualité, stabilité, gestes et matériel employés.</div>';}
  function renderRank(){const cur=C.currentProfessionalRank(JOB),next=C.nextProfessionalRank(JOB);if(!next){$('#alchemistRank').innerHTML=`<div class="notice success">👑 Grade professionnel maximal atteint : <b>${esc(cur?.name||C.jobRank(JOB))}</b>. Le grade est acquis ; la consécration professionnelle se poursuit dans l’onglet Maîtrise.</div>`;return;}const chk=rankCheck(next),levelBadge=`<span class="badge ${chk.levelOk?'success':'warning'}">Niveau métier ${S().level}/${next.minLevel}</span>`,villageBadge=`<span class="badge ${chk.villageOk?'success':'warning'}">Village ${C.state.level}/${next.minVillageLevel}</span>`,reqRows=chk.items.map(x=>{const label=x.k==='trustedClients'?`Commanditaires confiance ≥ ${x.meta?.trustThreshold||25}`:(rankLabels[x.k]||x.k);return `<span class="badge ${x.ok?'success':'warning'}">${esc(label)} ${Math.round(x.got)}/${x.want}</span>`;}).join(' ');$('#alchemistRank').innerHTML=`<div class="notice subtle">Grade actuel : <b>${esc(cur?.name||'Novice')}</b> · prochaine promotion : <b>${esc(next.name)}</b>. Les promotions croisent désormais pratique, savoir, qualité et confiance professionnelle.</div><div style="margin-top:10px">${levelBadge} ${villageBadge} ${reqRows}</div><button class="btn primary" id="alchemistPromote" style="margin-top:10px" ${chk.ok?'':'disabled'}>🎖️ Obtenir le grade ${esc(next.name)}</button>`;const b=$('#alchemistPromote');if(b)b.onclick=promote;}
  function renderClients(){const tier=reputationTier(),nextTier=tiers().find(t=>Number(t.minReputation||0)>Number(S().reputation||0));$('#alchemistClients').innerHTML=`<div class="notice subtle">${tier?.icon||'🧪'} Renommée : <b>${esc(tier?.name||'')}</b> · réputation ${Math.round(S().reputation||0)}/100${nextTier?` · prochain palier à ${nextTier.minReputation}`:' · palier maximal'} · actifs ${S().activeContracts.length}/${activeLimit()} · offres ${offerLimit()}.</div><div class="card-grid" style="margin-top:10px">${clients().map(c=>{const open=(!c.masterOnly||S().masterCertified)&&rankOrder()>=Number(c.minRank||0),tr=trust(c.id),active=open?clientPerks(c):[],next=(c.trustPerks||[]).find(p=>tr<Number(p.minTrust||0));return `<article class="contract-card ${open?'':'locked'}"><div class="contract-card-head"><h3>${c.icon} ${esc(c.name)}</h3><span class="badge">${open?`Confiance ${Math.round(tr)}`:'🔒'}</span></div><p>${esc(c.description)}</p><small><b>${open?esc(clientStatus(tr)):`Grade ${Number(c.minRank||0)}`}</b>${open&&c.focus?` · ${esc(c.focus)}`:''}</small><div class="career-perks">${active.map(p=>`<span>✓ ${esc(p.label)}</span>`).join('')||(open?'<span>Aucun avantage relationnel actif</span>':'<span>Commanditaire pas encore accessible</span>')}</div><small>${open?(next?`Prochain avantage à ${next.minTrust} confiance : ${esc(next.label)}`:'Tous les avantages relationnels sont actifs'):`Se débloque au grade professionnel ${Number(c.minRank||0)}`}</small></article>`;}).join('')}</div>`;}
  function renderOffers(){refreshOffers();const offers=S().contractOffers;$('#alchemistOffers').innerHTML=offers.length?offers.map(o=>{const d=contracts().find(x=>x.id===o.contractId),c=clients().find(x=>x.id===d?.clientId);return `<article class="contract-card"><div class="contract-card-head"><h3>${d?.icon||'📜'} ${esc(d?.name)}</h3><span class="badge">${d?.quantity||0} × ${esc(resourceDef(d?.resourceId)?.name||'')}</span></div><p>${c?.icon||'👤'} ${esc(c?.name||'')} · ${esc(d?.category||'contrat')}</p><small>${esc(criteriaText(d))}</small><small>Base : ${d?.reward?.treasury||0} couronnes · +${d?.reward?.reputation||0} réputation · confiance +${d?.reward?.trust||0}</small><button class="btn primary" data-accept="${o.id}" ${S().activeContracts.length>=activeLimit()?'disabled':''}>Accepter</button></article>`;}).join(''):'<div class="empty-state">Aucune proposition actuellement accessible. Étudie les formules, progresse en grade et développe la confiance des commanditaires.</div>';document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>acceptContract(b.dataset.accept));}
