  window.alchemistBuyTool=id=>{ensure();const t=alchTool(id);if(!t||ownsTool(id)||!meetsGate(t))return;const price=Number(t.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S().ownedTools.push(id);S().toolCondition[id]=toolMax(id);S().toolXp[id]=0;if(!S().equippedTools[t.operation])S().equippedTools[t.operation]=id;S().stats.equipmentBought++;S().stats.toolsBought++;S().stats.equipmentSpent+=price;C.log(`🧰 Matériel alchimique acheté : ${t.name}.`);C.evaluateAchievements?.(false);C.save();render();};
  window.alchemistEquipTool=id=>{ensure();const t=alchTool(id);if(!t||!ownsTool(id)||!meetsGate(t))return;S().equippedTools[t.operation]=id;C.log(`🧰 ${t.name} installé au poste ${t.operation}.`);C.save();render();};
  window.alchemistRepairTool=id=>{ensure();const t=alchTool(id);if(!t||!ownsTool(id)||toolCondition(id)>=toolMax(id)-.5)return;const cost=repairCost(id);if(cost<=0&&t.starter&&toolCondition(id)<=0){S().toolCondition[id]=Math.round(toolMax(id)*.25);C.log(`🔧 Remise en état de secours : ${t.name} revient à 25 %.`);}else{if(Number(C.state.treasury||0)<cost)return alert(`Il faut ${cost} couronnes.`);C.state.treasury-=cost;S().toolCondition[id]=toolMax(id);S().stats.repairs++;S().stats.maintenanceSpent+=cost;C.log(`🔧 ${t.name} entretenu pour ${cost} couronnes.`);}C.save();render();};
  window.alchemistBuyGear=id=>{ensure();const g=alchGear(id);if(!g||ownsGear(id)||!meetsGate(g))return;const price=Number(g.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S().ownedGear.push(id);if(!S().equippedGear[g.slot])S().equippedGear[g.slot]=id;S().stats.equipmentBought++;S().stats.gearBought++;S().stats.equipmentSpent+=price;C.log(`⚗️ Installation de laboratoire achetée : ${g.name}.`);C.evaluateAchievements?.(false);C.save();render();};
  window.alchemistEquipGear=id=>{ensure();const g=alchGear(id);if(!g||!ownsGear(id)||!meetsGate(g))return;S().equippedGear[g.slot]=id;C.log(`⚗️ ${g.name} installé au laboratoire.`);C.save();render();};
  window.alchemistSellLoose=(id,all=false)=>{ensure();refreshMarket();const qtyAvail=looseQty(id),m=marketItem(id);if(!m||qtyAvail<=0)return;const qty=all?qtyAvail:1,total=Math.round(looseUnitPrice(id)*qty*100)/100;if(!C.consumeResource(id,qty,'Vente alchimique non traçable'))return;C.state.treasury=Number(C.state.treasury||0)+total;S().stats.marketSales+=qty;S().stats.looseSales+=qty;S().stats.marketRevenue+=total;S().marketDemand[id]=clamp(marketDemand(id)-qty*.006,Number(m.minDemand||.7),Number(m.maxDemand||1.6));C.log(`💰 Stock alchimique courant vendu : ${fmt(qty)} × ${m.name} pour ${total.toFixed(2)} couronnes.`);C.evaluateAchievements?.(false);C.save();render();};
  window.alchemistSellLot=id=>{ensure();refreshMarket();const l=S().alchemicalLots.find(x=>x.id===id&&Number(x.quantity||0)>0),m=marketItem(l?.resourceId);if(!l||!m)return;const qty=Number(l.quantity||0),total=lotPrice(l);if(C.resource(l.resourceId)<qty)return alert('Le stock partagé ne contient plus ce lot.');if(!C.consumeResource(l.resourceId,qty,'Vente lot alchimique traçable'))return;S().alchemicalLots=S().alchemicalLots.filter(x=>x.id!==id);C.state.treasury=Number(C.state.treasury||0)+total;S().stats.marketSales+=qty;S().stats.traceableSales+=qty;S().stats.marketRevenue+=total;S().marketDemand[l.resourceId]=clamp(marketDemand(l.resourceId)-qty*.008,Number(m.minDemand||.7),Number(m.maxDemand||1.6));C.log(`💰 Lot alchimique vendu : ${fmt(qty)} ${m.name.toLowerCase()}, Q${Math.round(l.quality||0)}, stabilité ${Math.round(l.stability||0)} %, pour ${total} couronnes.`);C.evaluateAchievements?.(false);C.save();render();};
  window.alchemistChooseSpec=id=>{ensure();const d=specDef(id);if(!d||S().level<Number(d.minLevel||5)||rankOrder()<Number(d.minRank||2))return;if(!S().specialization.primary){S().specialization.primary=id;C.log(`🧭 Spécialisation principale Alchimiste : ${d.name}.`);}else if(S().specialization.primary!==id&&!S().specialization.secondary&&rankOrder()>=5&&spentInSpec(S().specialization.primary)>=4){S().specialization.secondary=id;C.log(`🧭 Spécialisation secondaire Alchimiste : ${d.name}.`);}C.save();render();};
  window.alchemistInvestTalent=(specId,talentId)=>{ensure();const d=specDef(specId),t=d?.talents?.find(x=>x.id===talentId);if(!d||!t||!canInvestTalent(specId,t))return;S().specialization.talents[t.id]=true;S().stats.specializationTalents=Object.values(S().specialization.talents).filter(Boolean).length;C.log(`✨ Talent Alchimiste : ${t.name}.`);C.evaluateAchievements?.(false);C.save();render();};
  window.alchemistRespec=()=>{ensure();const spent=specPointsSpent(),cost=20+spent*10;if(!S().specialization.primary)return;if(Number(C.state.treasury||0)<cost)return alert(`Il faut ${cost} couronnes pour réorienter la carrière.`);C.state.treasury-=cost;S().stats.specializationRespecSpent+=cost;S().specialization={primary:null,secondary:null,talents:{}};S().stats.specializationTalents=0;C.log(`🧭 Réorientation Alchimiste effectuée pour ${cost} couronnes.`);C.save();render();};

  function renderResearch(){ensure();const done=researchProjects().filter(pg=>researchCompleted(pg.id)).length;$('#alchemistResearchProjects').innerHTML=`<div class="economy-summary"><div><span>Protocoles achevés</span><b>${done}/${researchProjects().length}</b></div><div><span>Étapes validées</span><b>${S().stats.researchStages||0}/12</b></div><div><span>Synthèses</span><b>${S().stats.catalystSyntheses||0}</b></div><div><span>Lots uniques</span><b>${S().stats.uniqueBatches||0}</b></div></div><div class="notice subtle" style="margin-top:10px">Chaque protocole comporte trois étapes. Les preuves de carrière ouvrent l’étape ; ses ressources sont consommées au lancement. Le dernier jalon révèle définitivement un catalyseur et/ou une formule unique.</div><div class="card-grid" style="margin-top:10px">${researchProjects().map(pg=>{const ps=projectState(pg.id),done=!!ps.completed,st=(pg.stages||[])[Number(ps.stage||0)],rows=st?researchRequirementRows(pg,st):[],costs=st?researchCostRows(st):[],ready=!!st&&rows.every(x=>x.ok)&&costs.every(x=>x.have>=x.need)&&!activeTask(),unlock=[pg.unlockCatalystId?`💎 ${catalyst(pg.unlockCatalystId)?.name||pg.unlockCatalystId}`:'',pg.unlockRecipeId?`📜 ${recipe(pg.unlockRecipeId)?.name||pg.unlockRecipeId}`:''].filter(Boolean).join(' · ');return `<article class="contract-card ${done?'completed':ready?'':'locked'}"><div class="contract-card-head"><h3>${pg.icon||'📚'} ${esc(pg.name)}</h3><span class="badge">${done?'Achevé':`Étape ${Number(ps.stage||0)+1}/${(pg.stages||[]).length}`}</span></div><p>${esc(pg.description||'')}</p>${unlock?`<small><b>Déblocage final :</b> ${esc(unlock)}</small>`:''}${done?'<div class="notice success" style="margin-top:8px">✓ Protocole intégré au corpus du laboratoire.</div>':`<div class="notice subtle" style="margin-top:8px"><b>${esc(st?.name||'Étape')}</b><br>${esc(st?.description||'')}</div><div class="requirement-list">${rows.map(r=>`<div class="${r.ok?'ok':'missing'}"><span>${r.ok?'✓':'○'} ${esc(r.label)}</span><b>${Math.round(r.have)}/${Math.round(r.need)}</b></div>`).join('')}</div><small>Coût : ${costs.map(c=>`${c.icon} ${fmt(c.need)} ${esc(c.name)} (${fmt(c.have)})`).join(' · ')}</small><br><button class="btn primary" onclick="alchemistBeginResearch('${pg.id}')" ${ready?'':'disabled'}>📚 Lancer cette étape</button>`}</article>`;}).join('')}</div>`;
    $('#alchemistCatalysts').innerHTML=`<div class="card-grid">${catalysts().map(c=>{const unlock=catalystUnlocked(c),purity=catalystStockPurity(c.resourceId),cost=catalystOperatingCost(c),risk=Math.round(catalystFailureChance(c)*100);return `<article class="contract-card ${unlock?'':'locked'}"><div class="contract-card-head"><h3>${c.icon||'💎'} ${esc(c.name)}</h3><span class="badge">${unlock?`Stock ${fmt(C.resource(c.resourceId))}`:'🔒 Recherche'}</span></div><p>${esc(c.description||'')}</p><small>Niv. ${c.minLevel} · grade ${c.minRank} · risque ${risk}% · consommables ${cost.toFixed(2)} 🪙 · pureté moyenne en réserve ${purity?`${Math.round(purity)}%`:'—'}</small><div class="notice subtle" style="margin-top:8px">${Object.entries(c.inputs||{}).map(([id,q])=>`${resourceDef(id)?.icon||'•'} ${q} ${esc(resourceDef(id)?.name||id)} (${fmt(C.resource(id))})`).join(' · ')}</div><button class="btn primary" onclick="alchemistBeginCatalyst('${c.id}')" ${unlock&&catalystAvailability(c)&&Number(C.state.treasury||0)>=cost&&!activeTask()?'':'disabled'}>💎 Synthétiser</button></article>`;}).join('')}</div>`;
    const lots=S().catalystLots.filter(l=>Number(l.quantity||0)>0);$('#alchemistCatalystLots').innerHTML=lots.length?`<div class="card-grid">${lots.map(l=>`<article class="contract-card"><div class="contract-card-head"><h3>${catalyst(l.catalystId)?.icon||'💎'} ${esc(resourceDef(l.resourceId)?.name||l.resourceId)}</h3><span class="badge ${Number(l.purity||0)>=85?'success':''}">Pureté ${Math.round(l.purity||0)}%</span></div><p>${fmt(l.quantity)} unité(s) · matière d’origine Q${Math.round(l.inputQuality||45)}</p><small>${Number(l.traceableInput||0)>0?'Origine botanique traçable · ':''}les lots les plus purs sont consommés en priorité par les formules uniques.</small></article>`).join('')}</div>`:'<div class="empty-state">Aucun catalyseur qualitatif en réserve.</div>';
  }
  window.alchemistBeginResearch=id=>beginResearch(id);window.alchemistBeginCatalyst=id=>beginCatalyst(id);

  function renderEquipment(){const opLabels={prepare:'Préparation',heat:'Chauffe',stabilize:'Stabilisation'},slotLabels={bench:'Paillasse',safety:'Protection',reference:'Documentation',storage:'Verrerie & stockage'};$('#alchemistTools').innerHTML=`<div class="notice subtle">Les trois postes de paillasse s’usent réellement. Leur état et leur maîtrise modifient vitesse, risque, qualité, stabilité et rendement.</div><div class="card-grid" style="margin-top:10px">${tools().map(t=>{const own=ownsTool(t.id),equipped=S().equippedTools[t.operation]===t.id,gate=meetsGate(t),pct=Math.round(toolConditionPct(t.id)),cost=repairCost(t.id);return `<article class="contract-card ${gate?'':'locked'}"><div class="contract-card-head"><h3>${t.icon} ${esc(t.name)}</h3><span class="badge">${opLabels[t.operation]||t.operation}</span></div><p>${esc(t.description)}</p><small>Niv. ${t.level} · grade ${t.minRank} · efficacité ×${Number(t.efficiency||1).toFixed(2)} · durabilité ${Math.round(t.maxDurability||100)}${own?` · maîtrise ${toolMastery(t.id)}/10 · état ${conditionLabel(t.id)} (${pct}%)`:''}</small><div class="button-row">${!own?`<button class="btn primary" onclick="alchemistBuyTool('${t.id}')" ${gate&&Number(C.state.treasury||0)>=Number(t.price||0)?'':'disabled'}>Acheter · ${t.price} 🪙</button>`:`<button class="btn ${equipped?'primary':''}" onclick="alchemistEquipTool('${t.id}')" ${equipped?'disabled':''}>${equipped?'✓ Installé':'Installer'}</button><button class="btn" onclick="alchemistRepairTool('${t.id}')" ${toolCondition(t.id)<toolMax(t.id)-.5?'':'disabled'}>🔧 ${cost?`${cost} 🪙`:'Secours'}</button>`}</div></article>`;}).join('')}</div>`;$('#alchemistGear').innerHTML=`<div class="card-grid">${gearDefs().map(g=>{const own=ownsGear(g.id),equipped=S().equippedGear[g.slot]===g.id,gate=meetsGate(g),effects=Object.entries(g.effects||{}).map(([k,v])=>`${k} ${Math.abs(Number(v))<1?`${Number(v)>=0?'+':''}${Math.round(Number(v)*100)}%`:`${Number(v)>=0?'+':''}${v}`}`).join(' · ');return `<article class="contract-card ${gate?'':'locked'}"><div class="contract-card-head"><h3>${g.icon} ${esc(g.name)}</h3><span class="badge">${slotLabels[g.slot]||g.slot}</span></div><p>${esc(g.description)}</p><small>${esc(effects||'Équipement de base')} · niv. ${g.level} · grade ${g.minRank}</small><div class="button-row">${!own?`<button class="btn primary" onclick="alchemistBuyGear('${g.id}')" ${gate&&Number(C.state.treasury||0)>=Number(g.price||0)?'':'disabled'}>Acheter · ${g.price} 🪙</button>`:`<button class="btn ${equipped?'primary':''}" onclick="alchemistEquipGear('${g.id}')" ${equipped?'disabled':''}>${equipped?'✓ Installé':'Installer'}</button>`}</div></article>`;}).join('')}</div>`;}
  function renderEconomy(){refreshMarket();const rows=marketDefs().map(m=>{const d=marketDemand(m.id),loose=looseQty(m.id),trace=traceableQty(m.id),unit=looseUnitPrice(m.id);return `<article class="contract-card"><div class="contract-card-head"><h3>${resourceDef(m.id)?.icon||'🧪'} ${esc(m.name)}</h3><span class="badge ${demandClass(d)}">Demande ${demandLabel(d)} · ×${d.toFixed(2)}</span></div><p>${esc(m.description||'')}</p><small>Stock courant vendable : ${fmt(loose)} · lots traçables : ${fmt(trace)} · prix courant ${unit.toFixed(2)} 🪙/u.</small><div class="button-row"><button class="btn" onclick="alchemistSellLoose('${m.id}',false)" ${loose>=1?'':'disabled'}>Vendre 1</button><button class="btn primary" onclick="alchemistSellLoose('${m.id}',true)" ${loose>0?'':'disabled'}>Vendre le courant (${fmt(loose)})</button></div></article>`;}).join('');$('#alchemistMarket').innerHTML=`<div class="notice subtle">La demande se réajuste progressivement. Les contrats restent plus rémunérateurs pour les cahiers des charges stricts ; le marché écoule les surplus. Les lots qualitatifs valent davantage grâce à qualité, stabilité, traçabilité et contrôle technique.</div><div class="card-grid" style="margin-top:10px">${rows}</div>`;const lots=S().alchemicalLots.filter(l=>Number(l.quantity||0)>0&&marketItem(l.resourceId));$('#alchemistMarketLots').innerHTML=lots.length?`<div class="card-grid">${lots.map(l=>`<article class="contract-card"><div class="contract-card-head"><h3>${resourceDef(l.resourceId)?.icon||'🧪'} ${esc(resourceDef(l.resourceId)?.name||l.resourceId)}</h3><span class="badge">${lotPrice(l)} 🪙</span></div><p>${fmt(l.quantity)} u. · Q${Math.round(l.quality)} · stabilité ${Math.round(l.stability)}%${lotControlled(l)?' · sous contrôle':''}</p><small>${Number(l.traceableInput||0)>0?'Matières Herboriste traçables · ':''}valeur calculée sur la demande actuelle.</small><button class="btn primary" onclick="alchemistSellLot('${l.id}')">💰 Vendre ce lot</button></article>`).join('')}</div>`:'<div class="empty-state">Aucun lot qualitatif disponible pour une vente traçable.</div>';}
  function renderSpecializations(){const s=S(),free=specPointsFree(),spent=specPointsSpent(),primary=s.specialization.primary,secondary=s.specialization.secondary;$('#alchemistSpecializations').innerHTML=`<div class="notice subtle">Points disponibles : <b>${free}</b> · dépensés : ${spent}/${specPointTotal()}. Une voie principale s’ouvre au niveau 5 et grade 2. Au grade de Maître, une seconde voie peut être choisie après 4 talents dans la première.</div><div class="card-grid" style="margin-top:10px">${specDefs().map(d=>{const active=activeSpec(d.id),eligible=S().level>=Number(d.minLevel||5)&&rankOrder()>=Number(d.minRank||2),role=primary===d.id?'Principale':secondary===d.id?'Secondaire':'';return `<article class="contract-card ${active?'':'locked'}"><div class="contract-card-head"><h3>${d.icon} ${esc(d.name)}</h3><span class="badge">${role||(eligible?'Disponible':'🔒')}</span></div><p>${esc(d.description)}</p>${!active?`<button class="btn primary" onclick="alchemistChooseSpec('${d.id}')" ${eligible&&(!primary||(!secondary&&rankOrder()>=5&&spentInSpec(primary)>=4))?'':'disabled'}>Choisir cette voie</button>`:''}<div style="margin-top:8px">${(d.talents||[]).map(t=>{const got=hasTalent(t.id),can=canInvestTalent(d.id,t),req=(t.requires||[]).map(x=>d.talents.find(y=>y.id===x)?.name||x).join(', ');return `<div class="notice subtle" style="margin-top:6px"><b>${got?'✓':'○'} ${esc(t.name)}</b> · ${t.cost||1} pt<br><small>${esc(t.description)}${req?` · exige : ${esc(req)}`:''}</small>${active&&!got?`<br><button class="btn" onclick="alchemistInvestTalent('${d.id}','${t.id}')" ${can?'':'disabled'}>Investir</button>`:''}</div>`;}).join('')}</div></article>`;}).join('')}</div>${primary?`<div class="button-row" style="margin-top:10px"><button class="btn danger" onclick="alchemistRespec()">↻ Réorienter la carrière · ${20+spent*10} 🪙</button></div>`:''}`;}

  function renderScholarly(){ensure();expireExceptionalOrders();const active=activeAdvancedLab();$('#alchemistAdvancedLabs').innerHTML=`<div class="notice subtle">Une seule configuration avancée agit à la fois sur la production. Les annexes construites restent acquises ; change de configuration uniquement lorsque la paillasse est libre.${active?`<br><b>Configuration active :</b> ${active.icon} ${esc(active.name)}`:''}</div><div class="card-grid" style="margin-top:10px">${advancedLabs().map(l=>{const own=ownsAdvancedLab(l.id),isActive=active?.id===l.id,req=advancedLabRequirementRows(l),costs=advancedLabCostRows(l),ready=req.every(x=>x.ok)&&costs.every(x=>x.have>=x.need),effects=Object.entries(l.effects||{}).map(([k,v])=>`${k} ${Math.abs(Number(v))<1?`${Number(v)>=0?'+':''}${Math.round(Number(v)*100)}%`:`+${v}`}`).join(' · ');return `<article class="contract-card ${own?'':ready?'':'locked'}"><div class="contract-card-head"><h3>${l.icon} ${esc(l.name)}</h3><span class="badge ${isActive?'success':''}">${isActive?'Active':own?'Construite':'À construire'}</span></div><p>${esc(l.description)}</p><small>${esc(effects)}</small>${!own?`<div class="requirement-list">${req.map(x=>`<div class="${x.ok?'ok':'missing'}"><span>${x.ok?'✓':'○'} ${esc(x.label)}</span><b>${Math.round(x.have)}/${Math.round(x.need)}</b></div>`).join('')}</div><small>Coût : ${costs.map(c=>`${c.icon} ${fmt(c.need)} ${esc(c.name)} (${fmt(c.have)})`).join(' · ')}</small><br><button class="btn primary" onclick="alchemistBuildAdvancedLab('${l.id}')" ${ready?'':'disabled'}>🔨 Construire l’annexe</button>`:`<button class="btn ${isActive?'primary':''}" onclick="alchemistActivateAdvancedLab('${l.id}')" ${isActive||activeTask()?'disabled':''}>${isActive?'✓ Configuration active':'🔬 Activer cette configuration'}</button>`}</article>`;}).join('')}</div>`;
    $('#alchemistScholarlyNetworks').innerHTML=`<div class="notice subtle">La réputation savante est indépendante de la confiance commerciale. Publier un mémoire consomme un vrai lot qualitatif ; les mandats exceptionnels font ensuite progresser la reconnaissance du réseau.</div><div class="card-grid" style="margin-top:10px">${scholarlyNetworks().map(n=>{const st=networkState(n.id),joined=st.joined,req=networkRequirementRows(n),ready=req.every(x=>x.ok)&&Number(C.state.treasury||0)>=Number(n.joinCost||0),p=n.publication||{},lots=publicationLots(n),have=lots.reduce((a,l)=>a+Number(l.quantity||0),0),canPub=joined&&Number(st.publications||0)<Number(p.max||0)&&have>=Number(p.quantity||1)&&C.resource(p.resourceId)>=Number(p.quantity||1)&&Number(C.state.treasury||0)>=Number(p.treasury||0),perks=networkPerks(n),next=(n.perks||[]).find(x=>networkStanding(n.id)<Number(x.minStanding||0));return `<article class="contract-card ${joined?'':ready?'':'locked'}"><div class="contract-card-head"><h3>${n.icon} ${esc(n.name)}</h3><span class="badge ${joined?'success':''}">${joined?`Réputation ${Math.round(networkStanding(n.id))}/100`:'Non membre'}</span></div><p>${esc(n.description)}</p>${!joined?`<div class="requirement-list">${req.map(x=>`<div class="${x.ok?'ok':'missing'}"><span>${x.ok?'✓':'○'} ${esc(x.label)}</span><b>${Math.round(x.have)}/${Math.round(x.need)}</b></div>`).join('')}</div><button class="btn primary" onclick="alchemistJoinNetwork('${n.id}')" ${ready?'':'disabled'}>🤝 Rejoindre · ${n.joinCost} 🪙</button>`:`<div class="career-perks">${perks.map(x=>`<span>✓ ${esc(x.label)}</span>`).join('')||'<span>Aucun avantage savant actif</span>'}</div><small>${next?`Prochain avantage à ${next.minStanding} : ${esc(next.label)}`:'Tous les avantages sont actifs'} · publications ${st.publications||0}/${p.max||0}</small><br><button class="btn" onclick="alchemistPublishMemoir('${n.id}')" ${canPub?'':'disabled'}>📚 Publier : ${fmt(p.quantity||1)} ${esc(resourceDef(p.resourceId)?.name||p.resourceId)} Q≥${p.qualityMin||0}/S≥${p.stabilityMin||0} · ${p.treasury||0} 🪙</button>`}</article>`;}).join('')}</div>`;
    $('#alchemistExceptionalOrders').innerHTML=`<div class="economy-summary"><div><span>Mandats accomplis</span><b>${S().stats.exceptionalOrdersCompleted||0}/${exceptionalOrders().length}</b></div><div><span>Mandats actifs</span><b>${S().activeExceptionalOrders.length}/${exceptionalLimit()}</b></div><div><span>Chefs-d’œuvre Q/S≥94</span><b>${S().stats.exceptionalMasterworks||0}</b></div><div><span>Réputation savante gagnée</span><b>${S().stats.networkStandingEarned||0}</b></div></div><div class="card-grid" style="margin-top:10px">${exceptionalOrders().map(o=>{const done=exceptionalCompleted(o.id),a=S().activeExceptionalOrders.find(x=>x.orderId===o.id),eligible=exceptionalEligible(o),n=scholarlyNetwork(o.networkId),l=advancedLab(o.labId),lots=exceptionalMatchingLots(o),have=lots.reduce((x,y)=>x+Number(y.quantity||0),0),remain=a?Math.max(0,Math.ceil((a.dueAt-now())/1000)):0;return `<article class="contract-card ${done?'completed':a?'':eligible?'':'locked'}"><div class="contract-card-head"><h3>${o.icon} ${esc(o.name)}</h3><span class="badge ${done?'success':a?'warning':''}">${done?'✓ Accompli':a?`${remain}s`:`${esc(n?.name||'Réseau')}`}</span></div><p>${esc(o.description)}</p><small><b>${esc(l?.name||'Laboratoire')}</b> · réseau ≥${o.minStanding||0} · ${esc(exceptionalCriteriaText(o))} · ${o.quantity} ${esc(resourceDef(o.resourceId)?.name||o.resourceId)}</small>${a?`<div class="notice subtle" style="margin-top:8px">Lots conformes : <b>${fmt(have)}/${o.quantity}</b></div><button class="btn primary" onclick="alchemistDeliverExceptional('${a.id}')" ${have>=Number(o.quantity||0)&&C.resource(o.resourceId)>=Number(o.quantity||0)?'':'disabled'}>👑 Livrer le mandat</button>`:done?'':`<button class="btn primary" onclick="alchemistAcceptExceptional('${o.id}')" ${eligible&&S().activeExceptionalOrders.length<exceptionalLimit()?'':'disabled'}>📜 Accepter le mandat</button>`}</article>`;}).join('')}</div>`;}

  function rewardCareer(r={}){if(r.jobXp)C.gainJobXp(JOB,Number(r.jobXp));if(r.villageXp)C.gainVillageXp(Number(r.villageXp));if(r.reputation)S().reputation=clamp(Number(S().reputation||0)+Number(r.reputation));if(r.treasury)C.state.treasury=Math.max(0,Number(C.state.treasury||0)+Number(r.treasury));if(r.masteryXp)C.gainMastery(JOB,Number(r.masteryXp));}
  function masteryEffectText(e={}){const labels={knowledgeGain:'Connaissance',quality:'Qualité',stability:'Stabilité',failureReduction:'Risque réduit',trustGain:'Confiance gagnée',catalystPurity:'Pureté catalytique',uniqueQuality:'Qualité unique',uniqueStability:'Stabilité unique',networkGain:'Réputation savante',contractReward:'Récompenses contrats',marketBonus:'Prix de vente',repairDiscount:'Entretien réduit',activeContractSlots:'Contrat actif supplémentaire'};return Object.entries(e).map(([k,v])=>`${labels[k]||k} ${Math.abs(Number(v))<1?`${Number(v)>=0?'+':''}${Math.round(Number(v)*100)}%`:`${Number(v)>=0?'+':''}${v}`}`);}
  function sealRequirementRows(seal){const req=seal?.requirements||{},rows=[],add=(label,have,need,displayHave='',displayNeed='')=>{if(Number(need||0)>0)rows.push({label,have:Number(have||0),need:Number(need||0),displayHave,displayNeed,ok:Number(have||0)>=Number(need||0)});};add('Niveau du métier',S().level,seal?.minLevel||1);add('Grade professionnel',rankOrder(),seal?.minRank||0,C.jobRank(JOB),C.professionalRanks(JOB).find(r=>Number(r.order||0)===Number(seal?.minRank||0))?.name||seal?.minRank||0);const labels={studies:'Études de formules',diagnosticStudies:'Études diagnostiques',expertTechniques:'Gestes experts',successfulBatches:'Lots réussis',controlledBatches:'Lots sous contrôle',stableUnits:'Unités stables',remarkableBatches:'Lots remarquables',researchProjectsCompleted:'Recherches rares achevées',catalystSyntheses:'Synthèses catalytiques',highPurityCatalysts:'Catalyseurs Q≥85',uniqueBatches:'Lots uniques',advancedLabsBuilt:'Laboratoires avancés construits',exceptionalMasterworks:'Chefs-d’œuvre exceptionnels',contractsCompleted:'Contrats réussis',remarkableContracts:'Livraisons remarquables',networksJoined:'Réseaux savants rejoints',scholarlyPublications:'Publications savantes',exceptionalOrdersCompleted:'Mandats exceptionnels',reputation:'Réputation métier',endorsements:'Recommandations reçues'};for(const [key,label] of Object.entries(labels)){if(!Number(req[key]||0))continue;const have=key==='contractsCompleted'?S().completedContracts:key==='reputation'?S().reputation:key==='endorsements'?S().endorsements.length:Number(S().stats[key]||0);add(label,have,req[key]);}if(Number(req.formulaCount||0)>0){const lvl=Number(req.formulaLevel||1),count=recipes().filter(r=>knowledgeLevel(r.id)>=lvl).length;add(`Formules ${K_NAMES[lvl]||'connues'}`,count,req.formulaCount);}for(const [toolId,need] of Object.entries(req.toolMastery||{}))add(`Maîtrise ${alchTool(toolId)?.name||toolId}`,toolMastery(toolId),need);return rows;}
  function sealReady(seal){return !!seal&&!sealUnlocked(seal.id)&&sealRequirementRows(seal).every(r=>r.ok);}
  function masterRequirementRows(){const c=masterCareer();if(!c)return[];const rows=[],add=(label,have,need,displayHave='',displayNeed='')=>rows.push({label,have:Number(have||0),need:Number(need||0),displayHave,displayNeed,ok:Number(have||0)>=Number(need||0)});add('Niveau du village',C.state.level,c.minVillageLevel||6);add('Niveau du métier',S().level,c.minLevel||15);add('Grade professionnel',rankOrder(),c.minRank||5,C.jobRank(JOB),C.professionalRanks(JOB).find(r=>Number(r.order||0)===Number(c.minRank||5))?.name||c.minRank||5);add('Réputation métier',S().reputation,c.minReputation||0);add('Sceaux de maîtrise',S().masterySeals.length,c.minSeals||0);add('Recommandations',S().endorsements.length,c.minEndorsements||0);add('Formules maîtrisées',recipes().filter(r=>knowledgeLevel(r.id)>=3).length,c.minMasteredFormulae||0);add('Recherches rares',researchProjects().filter(pg=>researchCompleted(pg.id)).length,c.minResearchProjects||0);add('Laboratoires avancés',S().advancedLaboratories.owned.length,c.minAdvancedLabs||0);add('Réseaux savants',scholarlyNetworks().filter(n=>networkJoined(n.id)).length,c.minNetworks||0);add('Publications savantes',S().stats.scholarlyPublications||0,c.minPublications||0);add('Mandats exceptionnels',S().stats.exceptionalOrdersCompleted||0,c.minExceptionalOrders||0);add('Chefs-d’œuvre exceptionnels',S().stats.exceptionalMasterworks||0,c.minExceptionalMasterworks||0);if(c.requirePrimaryCapstone)rows.push({label:'Voie principale maîtrisée',have:primaryCapstoneDone()?1:0,need:1,displayHave:primaryCapstoneDone()?`${specDef(S().specialization.primary)?.name||'Voie'} maîtrisée`:'Capstone manquante',displayNeed:'1 voie',ok:primaryCapstoneDone()});if(c.requiredExceptionalOrder)rows.push({label:`Épreuve finale : ${exceptionalOrder(c.requiredExceptionalOrder)?.name||c.requiredExceptionalOrder}`,have:exceptionalCompleted(c.requiredExceptionalOrder)?1:0,need:1,displayHave:exceptionalCompleted(c.requiredExceptionalOrder)?'Accomplie':'Non accomplie',displayNeed:'Accomplie',ok:exceptionalCompleted(c.requiredExceptionalOrder)});return rows;}
  window.alchemistRequestEndorsement=id=>{ensure();const c=clients().find(x=>x.id===id);if(!canRequestEndorsement(c))return;S().endorsements.push(id);S().stats.endorsements=S().endorsements.length;S().reputation=clamp(Number(S().reputation||0)+2);C.gainVillageXp(5);C.log(`✍️ Recommandation obtenue : ${c.name} signe le dossier de maîtrise de l’Alchimiste.`);C.save();render();};
  window.alchemistClaimSeal=id=>{ensure();const seal=masterySeal(id);if(!seal||!sealReady(seal))return;S().masterySeals.push(seal.id);rewardCareer(seal.reward||{});C.log(`🏅 Sceau de maîtrise Alchimiste obtenu : ${seal.name}.`);C.save();render();};
  window.alchemistClaimMasterTitle=()=>{ensure();const c=masterCareer(),rows=masterRequirementRows();if(!c||S().masterCertified||!rows.every(r=>r.ok))return;S().masterCertified=true;S().masterCertifiedAt=now();rewardCareer(c.reward||{});const council=clients().find(x=>x.id==='alchemist_jurors_council');if(council)S().clientTrust[council.id]=Math.max(trust(council.id),Number(council.initialTrust||24));S().lastContractRefresh=0;C.log(`👑 Consécration professionnelle : l’Alchimiste devient ${c.name}. Les mandats du Conseil des alchimistes jurés sont désormais ouverts.`);C.evaluateAchievements?.();C.save();refreshOffers(true);render();};
  function renderMasterCareer(){ensure();const seals=masterySeals(),career=masterCareer(),rows=masterRequirementRows();$('#alchemistMasterySeals').innerHTML=`<div class="master-seal-grid">${seals.map(seal=>{const got=sealUnlocked(seal.id),sr=sealRequirementRows(seal),ready=sealReady(seal);return `<article class="master-seal ${got?'claimed':ready?'ready':''}"><div class="master-seal-head"><span>${seal.icon||'🏅'}</span><div><b>${esc(seal.name)}</b><small>${got?'Sceau obtenu':ready?'Validation disponible':'Dossier en cours'}</small></div></div><p>${esc(seal.description||'')}</p><div class="master-reqs">${sr.map(r=>`<div class="master-req ${r.ok?'ok':'missing'}"><span>${r.ok?'✓':'○'} ${esc(r.label)}</span><b>${r.displayHave?esc(r.displayHave):Math.round(r.have)} / ${r.displayNeed?esc(r.displayNeed):r.need}</b></div>`).join('')}</div><div class="career-perks">${masteryEffectText(seal.effects||{}).map(x=>`<span>${esc(x)}</span>`).join('')}</div>${got?'<div class="seal-stamp">✓ Validé</div>':`<button class="btn primary" onclick="alchemistClaimSeal('${seal.id}')" ${ready?'':'disabled'}>🏅 Faire valider ce sceau</button>`}</article>`;}).join('')}</div>`;const ordinary=clients().filter(c=>!c.masterOnly);$('#alchemistEndorsements').innerHTML=`<div class="notice subtle">À partir du grade Alchimiste expert et de 55 réputation, les commanditaires suffisamment confiants peuvent signer le dossier de consécration.</div><div class="endorsement-list">${ordinary.map(c=>{const got=hasEndorsement(c.id),need=endorsementThreshold(c),tr=trust(c.id),ready=canRequestEndorsement(c);return `<div class="endorsement-card ${got?'signed':''}"><span>${c.icon||'👤'}</span><div><b>${esc(c.name)}</b><small>${got?'Recommandation signée':`Confiance ${Math.round(tr)}/${need}`}</small></div>${got?'<strong>✓</strong>':`<button class="btn" onclick="alchemistRequestEndorsement('${c.id}')" ${ready?'':'disabled'}>Demander</button>`}</div>`;}).join('')}</div>`;$('#alchemistMasterCareer').innerHTML=career?`<div class="master-charter ${S().masterCertified?'certified':''}"><div class="master-charter-head"><span>${career.icon||'👑'}</span><div><small>${S().masterCertified?'Titre professionnel obtenu':'Dossier de maîtrise final'}</small><h3>${esc(career.name)}</h3></div></div><p>${esc(career.description||'')}</p><div class="master-reqs">${rows.map(r=>`<div class="master-req ${r.ok?'ok':'missing'}"><span>${r.ok?'✓':'○'} ${esc(r.label)}</span><b>${r.displayHave?esc(r.displayHave):Math.round(r.have)} / ${r.displayNeed?esc(r.displayNeed):r.need}</b></div>`).join('')}</div>${S().masterCertified?`<div class="master-certified-banner">👑 Maître juré depuis le ${new Date(S().masterCertifiedAt).toLocaleDateString('fr-FR')} · ${esc(specDef(S().specialization.primary)?.name||'Alchimiste')}</div><div class="career-perks">${masteryEffectText(career.effects||{}).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="notice subtle"><b>Conseil des alchimistes jurés :</b> ses mandats peuvent maintenant apparaître dans les propositions et prolongent la carrière après la consécration.</div>`:`<button class="btn primary master-claim" onclick="alchemistClaimMasterTitle()" ${rows.length&&rows.every(r=>r.ok)?'':'disabled'}>👑 Soumettre le dossier au Conseil de la Convergence</button>`}</div>`:'<p class="muted">Aucun parcours de maître configuré.</p>';}

  function renderFuture(){$('#alchemistFuture').innerHTML=`<div class="notice subtle"><b>Le Grand audit Alchimiste VIL0.3.16.7 est terminé.</b> La carrière complète rejoint officiellement les métiers de référence de Village : progression 1→15, vingt piliers de profondeur, recherche rare, consécration et boucle post-maîtrise sont validés ensemble.</div><div class="card-grid" style="margin-top:12px"><article class="contract-card"><h3>✅ Carrière finalisée</h3><p class="muted">L’Alchimiste reste distinct de l’Herboriste et peut désormais servir, avec les cinq autres carrières terminées, de standard de profondeur pour les prochains métiers.</p></article></div>`;}
  function renderProgression(){const s=S(),cap=C.jobXpCap(JOB);$('#alchemistProgression').innerHTML=`<div class="metric-grid"><div class="metric"><span>Niveau</span><b>${s.level}/15</b></div><div class="metric"><span>XP</span><b>${Math.round(s.xp)}/${Math.round(cap)}</b></div><div class="metric"><span>Études</span><b>${s.stats.studies}</b></div><div class="metric"><span>Lots réussis</span><b>${s.stats.successfulBatches}</b></div><div class="metric"><span>Lots ratés</span><b>${s.stats.failedBatches}</b></div><div class="metric"><span>Lots sous contrôle</span><b>${s.stats.controlledBatches}</b></div><div class="metric"><span>Équipements achetés</span><b>${s.stats.equipmentBought}</b></div><div class="metric"><span>Entretien</span><b>${fmt(s.stats.maintenanceSpent)} 🪙</b></div><div class="metric"><span>Consommables</span><b>${fmt(s.stats.consumablesSpent)} 🪙</b></div><div class="metric"><span>Ventes marché</span><b>${fmt(s.stats.marketSales)} u.</b></div><div class="metric"><span>Revenu marché</span><b>${fmt(s.stats.marketRevenue)} 🪙</b></div><div class="metric"><span>Lots traçables vendus</span><b>${fmt(s.stats.traceableSales)} u.</b></div><div class="metric"><span>Talents</span><b>${s.stats.specializationTalents}/${specPointTotal()}</b></div><div class="metric"><span>Gestes experts</span><b>${s.stats.expertTechniques}</b></div><div class="metric"><span>Contrats réussis</span><b>${s.completedContracts}</b></div><div class="metric"><span>Livraisons remarquables</span><b>${s.stats.remarkableContracts}</b></div><div class="metric"><span>Formules comprises</span><b>${s.stats.formulaeUnderstood}/${recipes().length}</b></div><div class="metric"><span>Recherche rare</span><b>${s.stats.researchProjectsCompleted||0}/${researchProjects().length}</b></div><div class="metric"><span>Catalyseurs Q≥85</span><b>${fmt(s.stats.highPurityCatalysts||0)}</b></div><div class="metric"><span>Lots uniques</span><b>${s.stats.uniqueBatches||0}</b></div><div class="metric"><span>Laboratoires avancés</span><b>${s.stats.advancedLabsBuilt||0}/${advancedLabs().length}</b></div><div class="metric"><span>Réseaux savants</span><b>${s.stats.networksJoined||0}/${scholarlyNetworks().length}</b></div><div class="metric"><span>Publications</span><b>${s.stats.scholarlyPublications||0}</b></div><div class="metric"><span>Mandats exceptionnels</span><b>${s.stats.exceptionalOrdersCompleted||0}/${exceptionalOrders().length}</b></div><div class="metric"><span>Sceaux de maîtrise</span><b>${s.masterySeals.length}/${masterySeals().length}</b></div><div class="metric"><span>Recommandations</span><b>${s.endorsements.length}</b></div><div class="metric"><span>Consécration</span><b>${s.masterCertified?'Maître juré':'En cours'}</b></div></div>`;}

  function alchemistSceneLabel(type){return ({study:'📖 Étude en cours',brew:'🧪 Préparation du lot',research:'🔬 Recherche rare',catalyst:'✨ Purification du catalyseur'})[type]||'🧪 Travail de laboratoire';}
  function updateWorkshopScene(){const scene=$('#alchemistScene'),label=$('#alchemistSceneStatus'),task=activeTask();if(!scene)return;const kind=task?.type||'idle';scene.dataset.taskKind=kind;scene.classList.toggle('is-working',kind!=='idle');if(label)label.textContent=kind==='idle'?'🧪 Paillasse prête pour un nouveau lot':alchemistSceneLabel(kind);}
  function triggerWorkshopActionPulse(){const scene=$('#alchemistScene');if(scene){scene.classList.remove('scene-burst');void scene.offsetWidth;scene.classList.add('scene-burst');setTimeout(()=>scene.classList.remove('scene-burst'),420);}if(!activeTask()){const label=$('#alchemistSceneStatus');if(label)label.textContent='⚗️ Manipulation engagée…';}}
  function bindWorkshopActionPulse(){const host=document.querySelector('section.job-workshop');if(!host||host.dataset.scenePulseBound)return;host.dataset.scenePulseBound='1';host.addEventListener('click',ev=>{const btn=ev.target.closest('button');if(btn&&btn.closest('.job-workshop'))triggerWorkshopActionPulse();});}
  function render(){ensure();completeTask();expireContracts();expireExceptionalOrders();renderMetrics();renderStatus();if(!C.built(BUILDING))return;renderRecipes();renderTask();renderKnowledge();renderTechniques();renderSkills();renderMethods();renderLots();renderResearch();renderRank();renderClients();renderOffers();renderContracts();renderHistory();renderEquipment();renderEconomy();renderSpecializations();renderMasterCareer();renderFuture();renderProgression();updateWorkshopScene();}
  window.alchemistBuildAdvancedLab=buildAdvancedLab;window.alchemistActivateAdvancedLab=activateAdvancedLab;window.alchemistJoinNetwork=joinScholarlyNetwork;window.alchemistPublishMemoir=publishScholarlyMemoir;window.alchemistAcceptExceptional=acceptExceptionalOrder;window.alchemistDeliverExceptional=deliverExceptionalOrder;
  window.VillageAlchemist={ensure,knowledgeLevel,knowledgeCap,skillLevel,toolMastery,toolScale,toolEffect,gearEffect,specEffect,specPointTotal,specPointsFree,batchOperatingCost,marketDemand,looseQty,traceableQty,looseUnitPrice,lotPrice,refreshMarket,techniqueUnlocked,selectedTechnique,setTechnique,beginStudy,beginBrew,failureChance,completeTask,refreshOffers,acceptContract,matchingLots,deliverContract,expireContracts,rankCheck,criteriaText,trustedClientCount,lotTechniqueGrade,lotControlled,researchCompleted,catalystUnlocked,catalystStockPurity,beginResearch,beginCatalyst,catalystFailureChance,ownsAdvancedLab,activeAdvancedLab,activeLabEffect,networkJoined,networkStanding,networkEffect,buildAdvancedLab,activateAdvancedLab,joinScholarlyNetwork,publishScholarlyMemoir,exceptionalEligible,exceptionalMatchingLots,acceptExceptionalOrder,deliverExceptionalOrder,sealUnlocked,sealReady,masterRequirementRows,careerEffect,render};
  ensure();UI?.initTabs({tabs:['knowledge','lots','research','scholarly','autonomy','career','equipment','economy','specialization','mastery','future','progression'],storageKey:'village_alchemist_tab',renderers:{activity:()=>{renderRecipes();renderTask();},knowledge:()=>{renderKnowledge();renderTechniques();renderSkills();renderMethods();},lots:renderLots,research:renderResearch,scholarly:renderScholarly,career:()=>{renderRank();renderClients();renderOffers();renderContracts();renderHistory();},equipment:renderEquipment,economy:renderEconomy,specialization:renderSpecializations,mastery:renderMasterCareer,future:renderFuture,progression:renderProgression}});bindWorkshopActionPulse();render();
  setInterval(()=>{const before=!!activeTask(),changed=completeTask(),expired=expireContracts(),exceptionalExpired=expireExceptionalOrders();if(changed||expired||exceptionalExpired||before)render();else{renderTask();renderContracts();}},1000);
